/** Raw stdout line for {@code fxq rate PAIR DATE --src N}. */
public String rate(String pair, LocalDate date, int src) {
    List<String> cmd = new ArrayList<>();
    cmd.add(bin.toString());
    cmd.add("rate");
    cmd.add(pair);
    cmd.add(date.toString());
    cmd.add("--src");
    cmd.add(String.valueOf(src));
    return run(cmd);
}

/**
 * Parses one quote line: {@code PAIR YYYY-MM-DD RATE [~N]}.
 * The trailing {@code ~N} tag marks a carried value; it must not be dropped.
 */
public static FxQuote parse(String line) {
    String[] t = line.trim().split("\\s+");
    if (t.length < 3) {
        throw new IllegalArgumentException("unexpected quote line: " + line);
    }
    int carry = 0;
    for (int i = 3; i < t.length; i++) {
        if (t[i].startsWith("~")) carry = Integer.parseInt(t[i].substring(1));
    }
    return new FxQuote(t[0], LocalDate.parse(t[1]), new BigDecimal(t[2]), carry);
}

