package service;

import domain.FxQuote;
import infra.FxqClient;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** FX rates for settlement and display, backed by the vendor CLI with a per-run cache. */
public class RateService {
    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    /** Default-source quote (display). May be carried from an earlier business day on holidays. */
    public FxQuote quote(String currency, LocalDate date) {
        return fetch(CurrencyPairs.pairOf(currency), date, DEFAULT_SRC);
    }

    /**
     * Rate applied to card transactions of the given KST settlement date.
     * On a vendor non-business day the default source only carries the previous value (tagged ~N),
     * so the day's own settlement reference value (src 2) is requested instead.
     */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        FxQuote q = quote(currency, date);
        if (!q.carried()) return q.rate();
        return fetch(q.pair(), date, SETTLEMENT_SRC).rate();
    }

    private FxQuote fetch(String pair, LocalDate date, int src) {
        return cache.computeIfAbsent(pair + "@" + date + "#src" + src, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date, src));
        });
    }

    public int vendorCalls() {
        return vendorCalls;
    }
}

